@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text">@recipe.Description</p>
                        <div class="mb-2">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span style="color: @(i <= recipe.AverageRating ? "gold" : "#ccc"); font-size: 1.2rem;">★</span>
                            }
                            <small class="text-muted ms-1">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</small>
                        </div>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" CurrentCount="recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">📝 Instructions</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span
            @onclick="() => Rate(star)"
            @onmouseover="() => hovered = star"
            @onmouseout="() => hovered = 0"
            style="cursor: pointer; font-size: 1.5rem; color: @(StarColor(star));">
            ★
        </span>
    }
    <span class="ms-2 text-muted">
        @if (submitted)
        {
            <span class="text-success">✓ Thanks! </span>
        }
        @displayAverage / 5 (@displayCount ratings)
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int CurrentCount { get; set; }

    private int hovered;
    private int selected;
    private bool submitted;
    private double displayAverage;
    private int displayCount;

    protected override void OnParametersSet()
    {
        displayAverage = CurrentAverage;
        displayCount = CurrentCount;
    }

    private string StarColor(int star)
    {
        if (hovered > 0)
            return star <= hovered ? "gold" : "#ccc";
        if (selected > 0)
            return star <= selected ? "gold" : "#ccc";
        return star <= displayAverage ? "gold" : "#ccc";
    }

    private void Rate(int stars)
    {
        selected = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            displayAverage = recipe.AverageRating;
            displayCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>📤 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<div class="row">
    <div class="col-md-8">
        <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <div class="mb-3">
                <label class="form-label" for="title">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="category">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Asian">Asian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label" for="ingredients">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="submission.Ingredients"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 large eggs" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="steps">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                    placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    </div>
</div>

@code {
    private RecipeSubmission submission = new();
    private string? errorMessage;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(submission.Title) ||
            string.IsNullOrWhiteSpace(submission.Category) ||
            string.IsNullOrWhiteSpace(submission.Ingredients) ||
            string.IsNullOrWhiteSpace(submission.Steps))
        {
            errorMessage = "Please fill in all fields.";
            return;
        }

        var recipe = RecipeService.AddRecipe(submission);
        Navigation.NavigateTo($"/recipe/{recipe.Id}");
    }
}

